/**
 * Sub-pixel resolution recovery in the browser — the JavaScript half of `app/boost.py`.
 *
 * `inswapper` works on a fixed 128x128 aligned crop, so a face larger than that is sampled
 * at less than 1:1 and everything finer is gone before the result is pasted back. `app/boost.py`
 * gets it back by sampling the crop several times at sub-pixel offsets and interleaving the
 * results. This is the same algorithm, for the browser.
 *
 * The two implementations are held together by a test, not by hope:
 * `tests/test_boost_parity.py` runs `tests/boost_parity.mjs` against fixtures generated by
 * the Python implementation and compares the canvases byte for byte. Change one and the
 * other fails.
 *
 * What is deliberately identical to the Python:
 *   - `phases()` — the same phase grid, same order.
 *   - `sourceRectForPhase()` — the same sampling geometry, to the float.
 *   - `interleave()` — an interleave, not an average. Averaging means upscaling each pass
 *     and blending the interpolated results, and measured against a known ground truth that
 *     scored *worse than a single pass*: the interpolation cost more detail than the phases
 *     added.
 *
 * What is deliberately different:
 *   - The sampling itself. Python uses `cv2.warpAffine` with cubic interpolation; here the
 *     browser's own `drawImage` resamples the video, which is faster (and GPU-accelerated on
 *     most devices) but not the same filter. The geometry is identical; the interpolation is
 *     not, and this file does not pretend otherwise.
 */

/** The aligned crop size `inswapper_128` is fixed to. */
export const ALIGN = 128;

/** The multipliers worth offering, matching `SCALES` in `app/boost.py`. */
export const SCALES = [1, 2, 3];

/**
 * The sub-pixel offsets for a `scale`x boost, in canvas pixels.
 *
 * A 2x boost is a 2x2 grid of half-pixel offsets, which after the 2x upscale onto the
 * canvas land on whole canvas pixels. That is the whole trick.
 */
export function phases(scale) {
  const options = [];
  // x outer, y inner: the same order as `app/boost.py`, so a pass written by one and read
  // by the other lands in the same slot. The interleave carries each pass's own phase and
  // would not care, but two implementations that disagree in the small are two
  // implementations that will disagree in the large.
  for (let x = 0; x < scale; x += 1) {
    for (let y = 0; y < scale; y += 1) options.push([x, y]);
  }
  return options;
}

/**
 * The source rectangle to sample for one phase, in source pixels.
 *
 * A phase of one canvas pixel is `1 / scale` of a crop pixel, and a crop pixel covers
 * `region.w / ALIGN` source pixels. Moving *towards* larger x therefore samples from further
 * right: the pass whose content sits one canvas pixel to the right at phase 1 is the pass
 * that starts one step further into the source. Getting this sign wrong lands every pass one
 * pixel out, which looks like a sharpening filter rather than a defect — it cost 4 dB in the
 * Python version before a ground-truth test caught it.
 */
export function sourceRectForPhase(region, scale, phaseX, phaseY) {
  const step = region.w / ALIGN;
  return {
    x: region.x + (phaseX / scale) * step,
    y: region.y + (phaseY / scale) * step,
    w: region.w,
    h: region.h,
  };
}

/**
 * Interleave phase-shifted swap results onto one `scale * ALIGN` canvas.
 *
 * `passes` is an array of `{ x, y, data, width, height, channels }` where `data` holds one
 * `ALIGN` square per pass. Returns `{ data, width, height, channels }`.
 *
 * Unfilled canvas pixels are an error rather than something to leave blank: with no pass
 * covering them the face has a hole in it.
 */
export function interleave(passes, scale, channels = 3) {
  if (scale < 2) throw new Error("interleave is for scale >= 2; a single pass needs nothing merged");
  if (passes.length !== scale * scale) {
    throw new Error(`a ${scale}x boost needs ${scale * scale} passes, got ${passes.length}`);
  }
  const size = ALIGN * scale;
  const out = new Uint8ClampedArray(size * size * channels);
  const seen = new Uint8Array(size * size);

  for (const pass of passes) {
    const { x: phaseX, y: phaseY, data, width, height } = pass;
    const passChannels = pass.channels ?? channels;
    if (width !== ALIGN || height !== ALIGN) {
      throw new Error(`a swap pass must return ${ALIGN}x${ALIGN}, got ${width}x${height}`);
    }
    if (passChannels !== channels) {
      throw new Error(`expected ${channels} channels per pass, got ${passChannels}`);
    }
    if (phaseX < 0 || phaseX >= scale || phaseY < 0 || phaseY >= scale) {
      throw new Error(`phase (${phaseX}, ${phaseY}) is outside a ${scale}x grid`);
    }
    for (let row = 0; row < ALIGN; row += 1) {
      const canvasRow = phaseY + scale * row;
      for (let col = 0; col < ALIGN; col += 1) {
        const canvasCol = phaseX + scale * col;
        const target = (canvasRow * size + canvasCol) * channels;
        if (seen[canvasRow * size + canvasCol]) {
          throw new Error(`two passes claim phase (${phaseX}, ${phaseY})`);
        }
        const source = (row * ALIGN + col) * channels;
        for (let channel = 0; channel < channels; channel += 1) {
          out[target + channel] = data[source + channel];
        }
        seen[canvasRow * size + canvasCol] = 1;
      }
    }
  }

  if (seen.includes(0)) {
    throw new Error(`${seen.length - seen.reduce((a, b) => a + b, 0)} canvas pixels were measured by no pass`);
  }
  return { data: out, width: size, height: size, channels };
}
